      "description": "Curated info about a Travel Destination",
      "attributes": [
        "Attraction",
        "Accommodation"
      ]
    },
    {
      "name": "Attraction",
      "description": "Point of interest within a destination"
    },
    {
      "name": "Accommodation",
      "description": "Place where a Traveler can stay"
    },
    {
      "name": "Itinerary",
